describe('No Results Found Message - API Empty List Handling', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display "No results found" message when API returns empty list', () => {
    cy.intercept('GET', '/api/search?q=nonexistent').as('searchEmpty');
    cy.get('[data-testid="search-input"]').type('nonexistent');
    cy.get('[data-testid="search-button"]').click();
    cy.wait('@searchEmpty');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .should('contain', 'No results found');

    cy.get('[data-testid="results-list"]')
      .should('not.exist');

    cy.get('[data-testid="results-count"]')
      .should('contain', '0');
  });

  it('should handle empty list with pagination and display correct message', () => {
    cy.intercept('GET', '/api/search?q=empty&page=1').as('searchEmptyPage1');
    cy.intercept('GET', '/api/search?q=empty&page=2').as('searchEmptyPage2');
    cy.get('[data-testid="search-input"]').type('empty');
    cy.get('[data-testid="search-button"]').click();
    cy.wait('@searchEmptyPage1');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .should('contain', 'No results found');

    cy.get('[data-testid="results-list"]')
      .should('not.exist');

    cy.get('[data-testid="pagination-controls"]')
      .should('not.exist');

    cy.get('[data-testid="results-count"]')
      .should('contain', '0');

    cy.get('[data-testid="pagination-button"]').click();
    cy.wait('@searchEmptyPage2');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .should('contain', 'No results found');
  });
});
